--
-- Structure de la vue `cm_par_enseignant`
--
DROP TABLE IF EXISTS `cm_par_enseignant`;

CREATE ALGORITHM=UNDEFINED DEFINER=`appia`@`%` SQL SECURITY DEFINER VIEW `cm_par_enseignant`  AS SELECT `seances`.`id_ens` AS `id_ens`, sum(`seances`.`duree_seance`) AS `tps_cm` FROM `seances` WHERE `seances`.`type_seance` = 'CM' GROUP BY `seances`.`id_ens` ;

