--
-- Structure de la vue `details`
--
DROP TABLE IF EXISTS `details`;

CREATE ALGORITHM=UNDEFINED DEFINER=`appia`@`%` SQL SECURITY DEFINER VIEW `details`  AS SELECT `e`.`id_ens` AS `id_ens`, `e`.`nom_ens` AS `nom_ens`, `e`.`prenom_ens` AS `prenom_ens`, `c`.`id_cours` AS `id_cours`, `c`.`intitule_cours` AS `intitule_cours`, `c`.`commentaire_cours` AS `commentaire_cours`, `a`.`annee_scolaire` AS `annee_scolaire`, `a`.`type_seance` AS `type_seance`, `a`.`duree_seance` AS `duree_seance`, `a`.`mutualisation` AS `mutualisation`, `a`.`commentaire_seance` AS `commentaire_seance`, `a`.`paiement` AS `paiement` FROM ((`enseignants` `e` join `seances` `a` on(`e`.`id_ens` = `a`.`id_ens`)) join `cours` `c` on(`a`.`id_cours` = `c`.`id_cours`)) ORDER BY `e`.`id_ens` ASC, `c`.`id_cours` ASC ;

